class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        if(head == nullptr || head->next == nullptr)
            return head;

        ListNode* newhead = reverseList(head->next);

        head->next->next = head;
        head->next = nullptr;

        return newhead;
    }
};

class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        ListNode dummy(0);
        auto cur = &dummy;
        int carry = 0;

        while (l1 || l2 || carry) {
            int sum = carry +
                     (l1 ? l1->val : 0) +
                     (l2 ? l2->val : 0);

            carry = sum / 10;
            cur = cur->next = new ListNode(sum % 10);

            if (l1) l1 = l1->next;
            if (l2) l2 = l2->next;
        }

        return dummy.next;
    }
};

