class Solution {
public:
    TreeNode* invertTree(TreeNode* root) {
        if(root == NULL) return NULL;

        invertTree(root->left);
        invertTree(root->right);

        TreeNode* temp = root->left;
        root->left = root->right;
        root->right = temp;

        return root;
    }
};

class MinStack {
public:
    stack<pair<int, int>> s;

    MinStack() {

    }

    void push(int value) {
        if(s.empty()){
            s.push({value, value});
        }
        else{
            int minVal = min(value, s.top().second);
            s.push({value, minVal});
        }
    }

    void pop() {
        s.pop()
    }

    int top() {
        return s.top().first;        
    }

    int getMin() {
        return s.top().second;
    }
};

